import dlapmr = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr( 'row-major', true, 3, 2, X, 2, K, 1 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr( 5, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( true, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( false, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( null, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( void 0, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( [], true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( {}, true, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( ( x: number ): number => x, true, 3, 2, X, 2, K, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a boolean...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr( 'row-major', '5', 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', 5, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', null, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', void 0, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', [], 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', {}, 3, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', ( x: number ): number => x, 3, 2, X, 2, K, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr( 'row-major', true, '5', 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, true, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, false, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, null, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, void 0, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, [], 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, {}, 2, X, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, ( x: number ): number => x, 2, X, 2, K, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a Float64Array...
{
	const K = new Int32Array( 3 );

	dlapmr( 'row-major', true, 3, 2, '5', 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, 5, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, true, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, false, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, null, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, void 0, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, [], 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, {}, 2, K, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, ( x: number ): number => x, 2, K, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a seventh argument which is not an Int32Array...
{
	const X = new Float64Array( 6 );

	dlapmr( 'row-major', true, 3, 2, X, 2, '5', 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, 5, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, true, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, false, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, null, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, void 0, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, [], 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, {}, 1 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr(); // $ExpectError
	dlapmr( 'row-major' ); // $ExpectError
	dlapmr( 'row-major', true ); // $ExpectError
	dlapmr( 'row-major', true, 3 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2 ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, K ); // $ExpectError
	dlapmr( 'row-major', true, 3, 2, X, 2, K, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float64Array...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectType Float64Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a boolean...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr.ndarray( '5', 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( 5, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( null, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( void 0, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( [], 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( {}, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( ( x: number ): number => x, 3, 2, X, 2, 1, 0, K, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a Float64Array...
{
	const K = new Int32Array( 3 );

	dlapmr.ndarray( true, 3, 2, '5', 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, 5, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, true, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, false, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, null, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, void 0, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, [], 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, {}, 2, 1, 0, K, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, ( x: number ): number => x, 2, 1, 0, K, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an eighth argument which is not an Int32Array...
{
	const X = new Float64Array( 6 );

	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, '5', 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, 5, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, true, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, false, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, null, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, void 0, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, [], 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, {}, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const X = new Float64Array( 6 );
	const K = new Int32Array( 3 );

	dlapmr.ndarray(); // $ExpectError
	dlapmr.ndarray( true ); // $ExpectError
	dlapmr.ndarray( true, 3 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, K ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, K, 1 ); // $ExpectError
	dlapmr.ndarray( true, 3, 2, X, 2, 1, 0, K, 1, 0, 10 ); // $ExpectError
}
